  function localPlan(text){
    const t=text.toLowerCase();const picks=[];
    const add=(id,why)=>{if(!picks.find(p=>p.id===id))picks.push({id,why})};
    if(/rider|courier|deliver|field|visit|logistic|sales team|agent|door/.test(t))add('field-track','Live routes and pin points for everyone on the move.');
    if(/call|phone|centre|center|dial|support|inbound|outbound/.test(t))add('dialer','Every call answered, scored and followed up automatically.');
    if(/instagram|tiktok|facebook|social|brand|content|reel|video|post/.test(t))add('social','Daily posts and reels, planned and published for you.');
    if(/lead|whatsapp|email|marketing|customer|sale|sell|store|shop|ecommerce|e-commerce/.test(t))add('marketer','Leads found, chats handled and deals closed on WhatsApp and email.');
    if(/remote|developer|office|staff|employee|team|people|hr|hiring/.test(t))add('lie-track','An honest picture of how every person works, remote or on-site.');
    if(/cod|cash|invoice|finance|payment|budget|profit|money|account/.test(t))add('finance','Cash flow, invoices and collections reconciled every day.');
    if(/photo|video|design|creative|campaign|ads/.test(t))add('content','Photos and videos generated to your monthly target.');
    add('ai-manager','Daily targets, check-ins and a night report for the whole team.');
    return {headline:'Your automation plan',summary:'Based on the nature of your business, these agents will run your daily operations, and each one feeds the next — reach becomes deals, deals become deliveries, deliveries become growth.',picks:picks.slice(0,5),growth:Math.min(92,55+picks.length*8)};
  }
  async function aiPlan(text){
    const names=AGENTS.map(a=>`${a.id}: ${a.name} — ${a.short}`).join('\n');
    const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:1000,messages:[{role:'user',content:`You are IntellioEra's solutions AI. Available agents:\n${names}\n\nBusiness description: """${text}"""\n\nRespond ONLY with JSON, no markdown: {"headline":"short plan title","summary":"2 sentences on how automation will run this business daily","picks":[{"id":"agent id","why":"one line specific to this business"}], "growth": number 60-95}. Choose 3-5 picks, most relevant first.`}]})});
    const d=await r.json();const txt=d.content.map(i=>i.text||'').join('').replace(/```json|```/g,'').trim();return JSON.parse(txt);
  }
