  /* globe */
  (function(){
    const cv=document.getElementById('globe'),ctx=cv.getContext('2d');
    const bits=atob("");const W=200,H=100;const land=[];
    for(let i=0;i<W*H;i++){const byte=bits.charCodeAt(i>>3);if(byte&(128>>(i&7)))land.push(i)}
    const pts=land.map(i=>{const lon=(i%W)/W*360-180+.9,lat=Math.floor(i/W)/H*180-90+.9;const la=lat*Math.PI/180,lo=lon*Math.PI/180;return [Math.cos(la)*Math.cos(lo),Math.sin(la),Math.cos(la)*Math.sin(lo)]});
    let rot=0,size=0,dpr=1;
    function fit(){dpr=Math.min(devicePixelRatio||1,2);size=cv.clientWidth;cv.width=size*dpr;cv.height=size*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
    let gvis=false;new IntersectionObserver(es=>es.forEach(e=>gvis=e.isIntersecting)).observe(cv);
    function frame(){
      if(!gvis){requestAnimationFrame(frame);return}
      if(size!==cv.clientWidth)fit();if(!size){requestAnimationFrame(frame);return}
      rot+=0.0025;ctx.clearRect(0,0,size,size);const R=size*.47,cx=size/2,cy=size/2;
      ctx.beginPath();ctx.arc(cx,cy,R,0,7);ctx.fillStyle='rgba(255,106,0,.05)';ctx.fill();ctx.strokeStyle='rgba(255,138,30,.25)';ctx.stroke();
      const cr=Math.cos(rot),sr=Math.sin(rot);
      for(const p of pts){const x=p[0]*cr-p[2]*sr,z=p[0]*sr+p[2]*cr,y=p[1];if(z<0)continue;
        const sx=cx+x*R,sy=cy-y*R;const a=.25+z*.75;ctx.fillStyle=`rgba(255,${170+Math.round(z*50)},110,${a})`;ctx.beginPath();ctx.arc(sx,sy,1.1+z*1.1,0,7);ctx.fill()}
      // Multiple global activity signals keep the visual location-neutral.
      const signals=[[38,-122],[40,-3],[25,55],[1,104],[-23,-46]];
      signals.forEach(([lat,lon],i)=>{const la=lat*Math.PI/180,lo=lon*Math.PI/180,p=[Math.cos(la)*Math.cos(lo),Math.sin(la),Math.cos(la)*Math.sin(lo)],x=p[0]*cr-p[2]*sr,z=p[0]*sr+p[2]*cr;if(z<=0)return;const sx=cx+x*R,sy=cy-p[1]*R,t=((performance.now()/1100)+i*.17)%1;ctx.beginPath();ctx.arc(sx,sy,3+t*13,0,7);ctx.strokeStyle=`rgba(255,179,71,${(1-t)*.75})`;ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.arc(sx,sy,3,0,7);ctx.fillStyle='#fff';ctx.fill()});
      requestAnimationFrame(frame);
    }
    frame();
  })();
  
  /* footer canvas */
  (function(){
    const f=document.querySelector('.footer');const cv=document.createElement('canvas');cv.className='foot-canvas';f.prepend(cv);const ctx=cv.getContext('2d');
    let W,H,P=[];function size(){W=cv.width=f.clientWidth;H=cv.height=f.clientHeight;P=Array.from({length:50},()=>({x:Math.random()*W,y:H+Math.random()*H,v:.2+Math.random()*.6,r:1+Math.random()*2,o:Math.random()}))}
    size();addEventListener('resize',size);
    let fvis=false;new IntersectionObserver(es=>es.forEach(e=>fvis=e.isIntersecting)).observe(f);
    (function g(){if(!fvis){requestAnimationFrame(g);return}if(W!==f.clientWidth||H!==f.clientHeight)size();ctx.clearRect(0,0,W,H);for(const p of P){p.y-=p.v;if(p.y<-10){p.y=H+10;p.x=Math.random()*W}ctx.fillStyle=`rgba(255,179,71,${.15+p.o*.5})`;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}
      // rising rings
      const t=(performance.now()/6000)%1;ctx.strokeStyle=`rgba(255,138,30,${.25*(1-t)})`;ctx.lineWidth=1;ctx.beginPath();ctx.arc(W*.85,H*.9,t*W*.6,0,7);ctx.stroke();requestAnimationFrame(g)})();
  })();
  
