  /* visibility-gated animation helper: pauses heavy canvases off-screen */
  window.gate=function(el,onVisible,onHidden){new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)onVisible();else onHidden&&onHidden()}),{threshold:0}).observe(el)};
  
  /* circuit-board integrations */
  (function(){
    const NAMES={whatsapp:'WhatsApp',gmail:'Gmail',telegram:'Telegram',twilio:'Twilio',microsoftteams:'Teams',instagram:'Instagram',facebook:'Facebook',linkedin:'LinkedIn',tiktok:'TikTok',youtube:'YouTube',x:'X',claude:'Claude',openai:'ChatGPT',googlegemini:'Gemini',meta:'Meta AI',salesforce:'Salesforce',hubspot:'HubSpot',slack:'Slack',notion:'Notion',googlesheets:'Sheets',microsoftexcel:'Excel',zapier:'Zapier',n8n:'n8n',googlecloud:'Google Cloud',amazonaws:'AWS',googledrive:'Drive',shopify:'Shopify',stripe:'Stripe',googlecalendar:'Calendar',trello:'Trello',asana:'Asana'};
    const BRAND={whatsapp:'#25D366',gmail:'#EA4335',telegram:'#26A5E4',twilio:'#F22F46',microsoftteams:'#6264A7',instagram:'#E4405F',facebook:'#0866FF',linkedin:'#0A66C2',tiktok:'#111',youtube:'#FF0000',x:'#111',claude:'#D97757',openai:'#111',googlegemini:'#8E75B2',meta:'#0467DF',salesforce:'#00A1E0',hubspot:'#FF7A59',slack:'#4A154B',notion:'#111',googlesheets:'#34A853',microsoftexcel:'#217346',zapier:'#FF4F00',n8n:'#EA4B71',googlecloud:'#4285F4',amazonaws:'#FF9900',googledrive:'#4285F4',shopify:'#7AB55C',stripe:'#635BFF',googlecalendar:'#4285F4',trello:'#0052CC',asana:'#F06A6A'};
    const L=[['whatsapp','gmail','telegram','twilio'],['instagram','facebook','linkedin','tiktok'],['claude','openai','googlegemini','meta'],['salesforce','hubspot','slack','notion']];
    const R=[['youtube','x','microsoftteams','zapier'],['googlesheets','microsoftexcel','n8n','trello'],['googlecloud','amazonaws','googledrive','asana'],['shopify','stripe','googlecalendar']];
    const W=1400,H=560,cx=700,cy=280,T=58,rows=[80,210,350,480];
    let s=`<svg viewBox="0 0 ${W} ${H}"><defs>
      <linearGradient id="cometGrad"><stop offset="0" stop-color="#FFB347" stop-opacity="0"/><stop offset="1" stop-color="#FFD08A"/></linearGradient>
      <linearGradient id="hubG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2a2320"/><stop offset="1" stop-color="#0d0b0a"/></linearGradient></defs>`;
    const side=(groups,dir)=>{
      groups.forEach((g,ri)=>{
        const y=rows[ri];const startX=cx+dir*150,bendX=cx+dir*260;
        const xs=g.map((_,i)=>cx+dir*(330+i*110));
        const endX=xs[xs.length-1];
        // path from hub edge to row end (rounded elbow)
        const r=24,vs=y<cy?-1:1;
        const d=`M${startX} ${cy} H${bendX-dir*r} Q${bendX} ${cy} ${bendX} ${cy+vs*r} V${y-vs*r} Q${bendX} ${y} ${bendX+dir*r} ${y} H${endX}`;
        s+=`<path class="trace" d="${d}"/><path class="comet" d="${d}" style="animation-delay:${(ri*.9+(dir>0?.45:0))}s"/>`;
        s+=`<circle class="node" cx="${bendX}" cy="${y}" r="3.5"/>`;
        g.forEach((k,i)=>{const x=xs[i];s+=`<g class="tl" style="transform-origin:${x}px ${y}px"><title>${NAMES[k]}</title><rect class="tileI2" x="${x-T/2}" y="${y-T/2}" width="${T}" height="${T}"/><g transform="translate(${x-14},${y-14}) scale(1.1667)"><path d="${ICONS[k]}" fill="${BRAND[k]}"/></g><text class="nm" x="${x}" y="${y+T/2+16}">${NAMES[k]}</text></g>`});
      });
    };
    side(L,-1);side(R,1);
    s+=`<rect class="hub" x="${cx-150}" y="${cy-44}" width="300" height="88"/><text class="hubT" x="${cx}" y="${cy+6}" text-anchor="middle">Intellio<tspan>Era</tspan></text><text class="hubS" x="${cx}" y="${cy+30}" text-anchor="middle">SECURE CONNECTION</text>`;
    s+=`<rect x="${cx-150}" y="${cy-44}" width="300" height="88" rx="22" fill="none" stroke="rgba(255,138,30,.5)"><animate attributeName="stroke-opacity" values=".2;.9;.2" dur="2.4s" repeatCount="indefinite"/></rect></svg>`;
    const c=document.getElementById('cloud');c.className='circuit reveal';c.innerHTML=s;
  })();
  
