  /* ---------- router ---------- */
  const PAGES=[...document.querySelectorAll('.page')];
  function show(name){PAGES.forEach(p=>p.classList.toggle('active',p.dataset.page===name));window.scrollTo(0,0);watchReveal();if(name==='home')setTimeout(()=>window.placeJourney&&window.placeJourney(),50)}
  function go(h){location.hash=h}
  function route(){
    const h=location.hash||'#/';closeModal();closeLive();if(window.showLoader&&window.__routed)showLoader(600);window.__routed=true;
    if(h.startsWith('#/')){const n=h.slice(2)||'home';show(PAGES.find(p=>p.dataset.page===n)?n:'home')}
    else{const home=PAGES.find(p=>p.dataset.page==='home');if(!home.classList.contains('active'))show('home');const el=document.querySelector(h);if(el)setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'start'}),80)}
    document.querySelectorAll('.nav ul a.top').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===h));
  }
  addEventListener('hashchange',route);route();
  addEventListener('scroll',()=>{if(!(location.hash||'#/').startsWith('#/'))return;if(location.hash&&location.hash!=='#/')return;let cur='';document.querySelectorAll('.page.active section[id]').forEach(s=>{if(scrollY>=s.offsetTop-240)cur=s.id});document.querySelectorAll('.nav ul a.top').forEach(a=>a.classList.toggle('active',cur?a.getAttribute('href')==='#'+cur:a.getAttribute('href')==='#/'))},{passive:true});
  
